CREATE TABLE IF NOT EXISTS quota_reset_state (user_id INTEGER PRIMARY KEY, reset_seq INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota_admin_operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota_reset_cards (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,operation_id TEXT NOT NULL,issued_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE INDEX IF NOT EXISTS quota_cards_user ON quota_reset_cards(user_id,expires_at,used_at);
CREATE TABLE IF NOT EXISTS quota_reset_events (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,operation_id TEXT NOT NULL,card_id TEXT UNIQUE,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS quota_events_user ON quota_reset_events(user_id,created_at);
CREATE TRIGGER IF NOT EXISTS quota_reset_guard BEFORE INSERT ON quota_reset_events BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM usage_log WHERE user_id=NEW.user_id AND status='pending' AND created_at>NEW.created_at-300000) THEN RAISE(ABORT,'QUOTA_RESET_BUSY') END; SELECT CASE WHEN NEW.card_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM quota_reset_cards WHERE id=NEW.card_id AND user_id=NEW.user_id AND used_at IS NULL AND expires_at>NEW.created_at) THEN RAISE(ABORT,'RESET_CARD_UNAVAILABLE') END; SELECT CASE WHEN NEW.card_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user_subscription WHERE user_id=NEW.user_id AND expires_at>NEW.created_at) THEN RAISE(ABORT,'RESET_SUBSCRIPTION_REQUIRED') END; END;
CREATE TRIGGER IF NOT EXISTS quota_reset_apply AFTER INSERT ON quota_reset_events BEGIN INSERT INTO quota_reset_state(user_id,reset_seq,reset_at) VALUES(NEW.user_id,(SELECT COALESCE(MAX(rowid),0) FROM usage_log WHERE user_id=NEW.user_id),NEW.created_at) ON CONFLICT(user_id) DO UPDATE SET reset_seq=excluded.reset_seq,reset_at=excluded.reset_at; UPDATE quota_reset_cards SET used_at=NEW.created_at WHERE id=NEW.card_id AND user_id=NEW.user_id; END;
CREATE TRIGGER IF NOT EXISTS agent_credit_quota_reset BEFORE INSERT ON usage_log BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM user_subscription WHERE user_id=NEW.user_id AND expires_at>NEW.created_at) THEN RAISE(ABORT,'AGENT_SUBSCRIPTION_REQUIRED') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM user_subscription AS s WHERE s.user_id=NEW.user_id AND ((s.five_hour_limit>0 AND NEW.credit_micro+NEW.held_micro+(SELECT COALESCE(SUM(credit_micro+held_micro),0) FROM usage_log WHERE user_id=NEW.user_id AND rowid>COALESCE((SELECT reset_seq FROM quota_reset_state WHERE user_id=NEW.user_id),0) AND created_at>NEW.created_at-18000000)>s.five_hour_limit) OR (s.week_limit>0 AND NEW.credit_micro+NEW.held_micro+(SELECT COALESCE(SUM(credit_micro+held_micro),0) FROM usage_log WHERE user_id=NEW.user_id AND rowid>COALESCE((SELECT reset_seq FROM quota_reset_state WHERE user_id=NEW.user_id),0) AND created_at>NEW.created_at-604800000)>s.week_limit) OR (s.month_limit>0 AND NEW.credit_micro+NEW.held_micro+(SELECT COALESCE(SUM(credit_micro+held_micro),0) FROM usage_log WHERE user_id=NEW.user_id AND rowid>COALESCE((SELECT reset_seq FROM quota_reset_state WHERE user_id=NEW.user_id),0) AND created_at>NEW.created_at-2592000000)>s.month_limit))) THEN RAISE(ABORT,'AGENT_CREDIT_LIMIT') END; END;
DROP TRIGGER IF EXISTS agent_credit_quota;
